"import os\n\nroot_dir = r\"c:\\DepLor\\HTTH\\Team\\HaiTacTiHonServer\\src\\main\\java\"\nresults = []\n\nfor root, dirs, files in os.walk(root_dir):\n    for f in files:\n        if f.endswith(\".java\"):\n            path = os.path.join(root, f)\n            with open(path, \"r\", encoding=\"utf-8\", errors=\"ignore\") as fl:\n                lines = fl.readlines()\n            for idx, line in enumerate(lines):\n                if \"send_box_ThongBao_OK\" in line:\n                    start = max(0, idx - 12)\n                    end = min(len(lines), idx + 8)\n                    block = \"\".join(lines[start:end])\n                    lower_block = block.lower()\n                    if \"hướng dẫn\" in lower_block or \"huong dan\" in lower_block or \"huongdan\" in lower_block or \"luật chơi\" in lower_block or \"thể lệ\" in lower_block or \"quy tắc\" in lower_block:\n                        rel = os.path.relpath(path, root_dir)\n                        results.append((rel, idx + 1, line.strip(), block))\n\nprint(f\"Total found: {len(results)}\")\nfor rel, line_num, line_str, block in results:\n    print(f\"\\n==================== {rel}:{line_num} ====================\")\n    print(f\"Line: {line_str}\")\n    # Print excerpt\n    for l in block.splitlines():\n        print(\"  | \" + l)\n"